#!/bin/sh
cd "${0%/*}" || exit # Run from this directory
. ${WM_PROJECT_DIR:?}/bin/tools/RunFunctions # Tutorial run functions
#------------------------------------------------------------------------------
# copy cpu surface from resources directory
cp -rf \
"$FOAM_TUTORIALS"/resources/geometry/cpuCabinet \
constant/triSurface
runApplication blockMesh
runApplication surfaceFeatureExtract
runApplication snappyHexMesh -overwrite
runApplication $decompDict decomposePar
restore0Dir -processor
runParallel splitMeshRegions -cellZones -overwrite
runParallel topoSet -region domain0
#------------------------------------------------------------------------------
cd 切换当前工作目录。
cp 复制文件或目录。
blockMesh 读取 blockMeshDict，生成由六面体块组成的网格。
surfaceFeatureExtract 从表面提取特征线，供 snappyHexMesh 控制棱边细化。
snappyHexMesh 细化背景网格，贴合几何表面，并按设置生成边界层。结果覆盖当前网格。
decomposePar 把网格和场划分到多个处理器子域。
restore0Dir 将 0.orig 恢复为求解所用的 0 目录。
splitMeshRegions 按网格连通性或 cellZone 将网格拆分成多个区域。结果覆盖当前网格。通过并行包装函数执行，进程数与分区设置配套。
topoSet 按几何、网格属性和集合关系创建或修改 sets/zones。处理区域由 domain0 指定。通过并行包装函数执行，进程数与分区设置配套。
