moleculeProperties
{
N2
{
mass 46.5e-27;
diameter 4.17e-10;
internalDegreesOfFreedom 2;
omega 0.74;
}
O2
{
mass 53.12e-27;
diameter 4.07e-10;
internalDegreesOfFreedom 2;
omega 0.77;
