// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //
dimensions [0 1 -1 0 0 0 0];
internalField uniform (0 0 0);
boundaryField
{
walls
{
type noSlip;
}
top
{
type pressureInletOutletVelocity;
phi phi.air;
inletValue uniform (0 0 0);
value uniform (0 0 0);
}
bottom
{
type interstitialInletVelocity;
inletVelocity uniform (0 0 1.875);
value uniform (0 0 1.875);
phi phi.air;
alpha alpha.air;
}
frontAndBack
{
type symmetry;
}
}
// ************************************************************************* //
0/U.air 设置 U.air 的内部初值和边界条件。dimensions 为 [0 1 -1 0 0 0 0]，单位为 m/s。internalField 为 uniform (0 0 0)；uniform 表示所有内部单元采用相同初值。
walls 采用 noSlip，壁面速度为零。
top 采用 pressureInletOutletVelocity，出流时外推速度，流入时依据通量确定法向速度。参数为 phi phi.air，inletValue uniform (0 0 0)，value uniform (0 0 0)。
bottom 采用 interstitialInletVelocity。参数为 inletVelocity uniform (0 0 1.875)，value uniform (0 0 1.875)，phi phi.air，alpha alpha.air。
frontAndBack 采用 symmetry，按局部面法向施加对称约束。
