mkdir -p "$FOAM_RUN"
cp -r "$FOAM_TUTORIALS/lagrangian/icoUncoupledKinematicParcelDyMFoam/mixerVesselAMI2D" "$FOAM_RUN/mixerVesselAMI2D-reference"
cd "$FOAM_RUN/mixerVesselAMI2D-reference"
